import sys

def solve():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    rows = [input().strip() for _ in range(n)]

    for row in rows:
        if '1' not in row:
            print(-1)
            return

    INF = 10**9
    answer = INF

    for col in range(m):
        total = 0
        for row in rows:
            best = INF
            for j in range(m):
                if row[j] == '1':
                    d = abs(j - col)
                    d = min(d, m - d)
                    if d < best:
                        best = d
            total += best
        if total < answer:
            answer = total

    print(answer)

if __name__ == "__main__":
    solve()
